    private function do_watch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * get the list of most recent $trades for a particular $symbol
         *
         * @see https://www.luno.com/en/developers/api#tag/Streaming-API
         *
         * @param {string} $symbol unified $symbol of the $market to fetch $trades for
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
         * @param {int} [$limit] the maximum amount of    $trades to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=public-$trades trade structures~
         */
        $this->check_required_credentials();
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $symbolValue = $market['symbol'];
        $subscriptionHash = '/stream/' . $market['id'];
        $subscription = array( 'symbol' => $symbolValue );
        $wsUrl = $this->safe_string($this->urls['api'], 'ws');
        if ($wsUrl === null) {
            throw new ExchangeError($this->id . ' watchTrades() has no websocket url');
        }
        $url = $wsUrl . $subscriptionHash;
        $messageHash = 'trades:' . $symbolValue;
        $subscribe = array(
            'api_key_id' => $this->apiKey,
            'api_key_secret' => $this->secret,
        );
        $request = $this->deep_extend($subscribe, $params);
        $trades = Async\await($this->watch($url, $messageHash, $request, $subscriptionHash, $subscription));
        $limitResolved = $limit;
        if ($this->newUpdates) {
            $limitResolved = $trades->getLimit($symbolValue, $limit);
        }
        return $this->filter_by_since_limit($trades, $since, $limitResolved, 'timestamp', true);
    }

    public function handle_trades(Client $client, array $message, array $subscription) {
        //
        //     {
        //         "sequence": "110980825",
        //         "trade_updates": [],
        //         "create_update": {
        //             "order_id": "BXHSYXAUMH8C2RW",
        //             "type": "ASK",
        //             "price": "24081.09000000",
        //             "volume": "0.07780000"
        //         },
        //         "delete_update": null,
        //         "status_update": null,
        //         "timestamp": 1660598775360
        //     }
        //
        $rawTrades = $this->safe_list($message, 'trade_updates', array());
        $length = count($rawTrades);
        if ($length === 0) {
            return;
        }
        $symbol = $subscription['symbol'];
        $market = $this->market($symbol);
        $messageHash = 'trades:' . $symbol;
        $stored = $this->safe_value($this->trades, $symbol);
        if ($stored === null) {
            $limit = $this->safe_integer($this->options, 'tradesLimit', 1000);
            $stored = new ArrayCache($limit);
            $this->trades[$symbol] = $stored;
        }
        for ($i = 0; $i < count($rawTrades); $i++) {
            $rawTrade = $rawTrades[$i];
            $trade = $this->parse_trade($rawTrade, $market);
            $stored->append($trade);
        }
        $this->trades[$symbol] = $stored;
        $client->resolve($this->trades[$symbol], $messageHash);
    }

