    private function do_watch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         * watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
         *
         * @see https://www.luno.com/en/developers/api#tag/Streaming-API
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum amount of order book entries to return
         * @param {arrayConstructor} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->type] accepts l2 or l3 for level 2 or level 3 order book
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-book-structure order book structure~
         */
        $this->check_required_credentials();
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $symbolValue = $market['symbol'];
        $subscriptionHash = '/stream/' . $market['id'];
        $subscription = array( 'symbol' => $symbolValue );
        $wsUrl = $this->safe_string($this->urls['api'], 'ws');
        if ($wsUrl === null) {
            throw new ExchangeError($this->id . ' watchOrderBook() has no websocket url');
        }
        $url = $wsUrl . $subscriptionHash;
        $messageHash = 'orderbook:' . $symbolValue;
        $subscribe = array(
            'api_key_id' => $this->apiKey,
            'api_key_secret' => $this->secret,
        );
        $request = $this->deep_extend($subscribe, $params);
        $orderbook = Async\await($this->watch($url, $messageHash, $request, $subscriptionHash, $subscription));
        return $orderbook->limit();
    }

    public function handle_order_book(Client $client, array $message, array $subscription) {
        //
        //     {
        //         "sequence": "24352",
        //         "asks": [{
        //             "id": "BXMC2CJ7HNB88U4",
        //             "price": "1234.00",
        //             "volume": "0.93"
        //         }],
        //         "bids": [{
